"""Exercise actual binding setters and StateBlock operations with COM/IPC adapters.

The source must already contain all four ownership-only guards. Baseline is
derived by removing exactly those guards; unchanged production methods, smart
pointer, StateBlock transfer and reply macros are used for both variants.
"""
import argparse
import hashlib
import json
from pathlib import Path

FILES = {
    "device": "bridge/src/client/d3d9_device.cpp",
    "base": "bridge/src/client/base.h",
    "stateblock": "bridge/src/client/d3d9_stateblock.cpp",
    "device_base": "bridge/src/client/d3d9_device_base.h",
    "command": "bridge/src/util/util_bridgecommand.h",
}
SLOTS = (
    ("m_stateRecording->m_captureState.streams[StreamNumber]", "pLssStreamData"),
    ("m_state.streams[StreamNumber]", "pLssStreamData"),
    ("m_stateRecording->m_captureState.indices", "pLssIndexData"),
    ("m_state.indices", "pLssIndexData"),
)


def method(source, marker):
    if source.count(marker) != 1:
        raise ValueError(f"Unexpected production method layout: {marker}")
    start = source.index(marker)
    brace = source.index("{", start)
    level, end = 1, brace + 1
    while level and end < len(source):
        level += (source[end] == "{") - (source[end] == "}")
        end += 1
    if level:
        raise ValueError(f"Unclosed production method: {marker}")
    if marker.startswith("HRESULT Direct3DDevice9Ex_LSS"):
        start = source.rindex("template<bool EnableSync>", 0, start)
    return source[start:end] + "\n"


def setters(source):
    return "\n".join(method(source, f"HRESULT Direct3DDevice9Ex_LSS<EnableSync>::{name}(")
                     for name in ("SetStreamSource", "SetIndices"))


def replace_once(source, old, new):
    if source.count(old) != 1:
        raise ValueError(f"Expected exactly one production source fragment: {old}")
    return source.replace(old, new, 1)


def generate(source, output):
    text = {key: (source / path).read_text(encoding="utf-8") for key, path in FILES.items()}
    candidate = text["device"]
    baseline = candidate
    for target, resource in SLOTS:
        baseline = replace_once(baseline,
            f"        if (*{target} != {resource}) {{\n          {target} = MakeD3DAutoPtr({resource});\n        }}",
            f"        {target} = MakeD3DAutoPtr({resource});")
    output.mkdir(parents=True, exist_ok=True)
    def write(name, contents):
        (output / name).write_text(contents, encoding="utf-8")
    pointer_marker = "class D3DAutoPtr {"
    if text["base"].count(pointer_marker) != 1:
        raise ValueError("Unexpected production D3DAutoPtr layout")
    write("autoptr.inc", pointer_marker + text["base"].split(pointer_marker, 1)[1].split("class D3dBaseIdFactory", 1)[0])
    write("invalidate.inc", method(text["device_base"], "void invalidateDataState()"))
    macros = []
    for name in ("WAIT_FOR_SERVER_RESPONSE", "WAIT_FOR_OPTIONAL_SERVER_RESPONSE"):
        marker = f"#define {name}("
        if text["command"].count(marker) != 1:
            raise ValueError(f"Unexpected response macro layout: {name}")
        macros.append(marker + text["command"].split(marker, 1)[1].split("\n\n", 1)[0])
    write("responses.inc", "\n\n".join(macros) + "\n")
    write("stateblock.inc", "\n".join(method(text["stateblock"], marker) for marker in (
        "void Direct3DStateBlock9_LSS::StateTransfer(", "void Direct3DStateBlock9_LSS::LocalCapture(",
        "HRESULT Direct3DStateBlock9_LSS::Capture(", "HRESULT Direct3DStateBlock9_LSS::Apply(")))
    before, after = setters(baseline), setters(candidate)
    skip = replace_once(before, "      // NV-DXVK start: Observe binding equality in the existing state domain.",
        "      if (!m_stateRecording && *m_state.streams[StreamNumber] == pLssStreamData && (!pStreamData || (m_state.streamOffsets[StreamNumber] == OffsetInBytes && m_state.streamStrides[StreamNumber] == Stride))) return S_OK;\n"
        "      // NV-DXVK start: Observe binding equality in the existing state domain.")
    skip = replace_once(skip, "      // NV-DXVK start: Observe binding equality without changing reference ownership.",
        "      if (!m_stateRecording && *m_state.indices == pLssIndexData) return S_OK;\n"
        "      // NV-DXVK start: Observe binding equality without changing reference ownership.")
    domain = replace_once(after, "if (*m_stateRecording->m_captureState.streams[StreamNumber] != pLssStreamData)",
                         "if (*m_state.streams[StreamNumber] != pLssStreamData)")
    domain = replace_once(domain, "if (*m_stateRecording->m_captureState.indices != pLssIndexData)",
                          "if (*m_state.indices != pLssIndexData)")
    dirty = replace_once(after, "m_stateRecording->m_dirtyFlags.streams[StreamNumber] = true;", "/* missing dirty */")
    dirty = replace_once(dirty, "m_stateRecording->m_dirtyFlags.indices = true;", "/* missing dirty */")
    metadata = replace_once(after, "m_state.streamOffsets[StreamNumber] = OffsetInBytes;", "/* missing offset update */")
    metadata = replace_once(metadata, "m_state.streamStrides[StreamNumber] = Stride;", "/* missing stride update */")
    for name, methods in {
        "BaselineDevice": before, "CandidateDevice": after, "SkipCommandMutant": skip,
        "WrongDomainMutant": domain, "MissingDirtyMutant": dirty, "MissingMetadataMutant": metadata,
    }.items():
        write(f"{name}.inc", methods.replace("Direct3DDevice9Ex_LSS<EnableSync>", f"{name}<EnableSync>"))
    write("actual_binding_references.cpp", '#include "binding_reference_support.h"\n#include "binding_references.cpp"\n')
    write("source-hashes.json", json.dumps({FILES[key]: hashlib.sha256(value.encode()).hexdigest()
                                          for key, value in text.items()}, indent=2) + "\n")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", required=True, type=Path)
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    generate(args.source, args.output)
